import{z as o,x as s,o as A,c as d,q as r,j as t,D as B,d as E,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"事件策略案例与收束","description":"","frontmatter":{"title":"事件策略案例与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ed-case-map.md","filePath":"quant/ed-case-map.md","lastUpdated":1791063341000}'),h={name:"quant/ed-case-map.md"};function p(m,a,u,c,F,C){const n=s("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="事件策略案例与收束" tabindex="-1">事件策略案例与收束 <a class="header-anchor" href="#事件策略案例与收束" aria-label="Permalink to &quot;事件策略案例与收束&quot;">​</a></h1><div class="epigraph"><p>事件驱动的研究对象是「已知何时、未知何事」的日程本身；收束时把每类事件放回谱系坐标，比记住任何一个效应更重要。</p><footer>—— 据 MacKinlay, Journal of Economic Literature, 1997；Harris, Trading and Exchanges, 2003 整理</footer></div><p><a href="/quant/ed-event-risk-crowding">上一课</a>把三层风险写成限额；本课程到此收束。收束用五个案例回看主线：每个案例都是五元组的一次应用——实际时点、载荷、预期、窗口、流量——放回谱系坐标（时点确定性 × 载荷可预测性），再接上各自的风控换挡点。案例之后给课程地图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>回看本课程的谱系坐标：财报事件的时点基本确定、载荷未知；指数调整与期权到期把载荷的可预测性一路推高——前者的流量由规则给出，后者由公开持仓算出；宏观发布把时点的确定性推到秒、把载荷的不确定性推回最大；制度事件连时点都不完全确定，却以参与集合的变化给研究提供天然对照。五个案例按这条轴走一遍，看五元组在每一格怎么变。</p><p><span class="marginnote">术语翻译：五元组就是给每个事件填一张五行小表——实际时点（精确到时戳，不是日历格）、载荷（事件携带多大冲击）、预期（市场事先消化了多少）、窗口（前后各算几天）、流量（被迫成交的量有多大）。五个格子填齐，五类事件才放在同一把尺子上比较。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是五个案例共用同一张作业单：先填五元组——实际时点、载荷、预期、窗口、流量；再在谱系坐标（时点确定性 × 载荷可预测性）上定位；然后写明风控换挡点与一条最常犯的错法。作业单的价值在可比：五类事件的差异全部显形在同一组格子里，而不是散落在各自的叙事里。</p><p><span class="marginnote">直觉类比：谱系坐标像一张地图，横轴是「你有多早知道它何时发生」，纵轴是「你有多早知道它有多大」。财报知道日子但不知道大小；指数调整与期权到期连大小都能事先算出；宏观发布把日子精确到秒、大小却最不确定；制度事件两轴都模糊。</span></p><p><span class="marginnote">MacKinlay 1997 的事件研究综述把「窗口设计」列为决定统计功效的第一变量：窗太短漏掉漂移、窗太长稀释信号。五元组的窗口一栏正是这件事的工程化。</span></p><h3 id="案例-1-财报漂移" tabindex="-1">案例 1：财报漂移 <a class="header-anchor" href="#案例-1-财报漂移" aria-label="Permalink to &quot;案例 1：财报漂移&quot;">​</a></h3><p>第 1 课与第 6 课的组合。\\(T\\) 用实际时戳、分盘前盘后换轨；载荷与预期差由 <a href="/quant/pead-sue">SUE</a> 标准化，语气增量用<a href="/quant/earnings-call-tone">电话会语气</a>在事件簇内合并；窗口是公告后主窗加下一季副窗；流量账单独记公告溢价。风控换挡点：预告不混表、第四季反号前离场、扎堆日限额。错法：用日历格当 \\(T\\)，漂移首段全部漏掉。</p><h3 id="案例-2-指数调整" tabindex="-1">案例 2：指数调整 <a class="header-anchor" href="#案例-2-指数调整" aria-label="Permalink to &quot;案例 2：指数调整&quot;">​</a></h3><p>第 2 课。双时点结构：宣布窗吸收预期，生效窗由 <a href="/quant/close-auction-imbalance">收盘竞价不平衡</a> 的机制承接冲击；流量 \\(\\Delta w\\) 乘以跟踪规模可事先推算。风控换挡点：宣布窗防名单错判，生效窗防执行。错法：把回吐与留存用同一个哑变量去估。</p><h3 id="案例-3-期权到期" tabindex="-1">案例 3：期权到期 <a class="header-anchor" href="#案例-3-期权到期" aria-label="Permalink to &quot;案例 3：期权到期&quot;">​</a></h3><p>第 3 课。载荷是净 gamma 剖面：正 gamma 尾盘 pin 住，负 gamma 放大；窗口三段，到期次日把体制账结清。风控换挡点：剖面符号逐日重测，0DTE 让窗口变密。错法：「大 OI 行权价必被钉住」。</p><h3 id="案例-4-宏观发布" tabindex="-1">案例 4：宏观发布 <a class="header-anchor" href="#案例-4-宏观发布" aria-label="Permalink to &quot;案例 4：宏观发布&quot;">​</a></h3><p>第 4 课。秒级时点、实时口径数据、标准化意外；三段窗口（事前撤退、发布跳、恢复）各记各的账。风控换挡点：修订值禁入事件表，事前窗成本单列。错法：用修订后 GDP 回测公告反应。</p><h3 id="案例-5-制度变化" tabindex="-1">案例 5：制度变化 <a class="header-anchor" href="#案例-5-制度变化" aria-label="Permalink to &quot;案例 5：制度变化&quot;">​</a></h3><p>第 5 课。时间线三段、四条通道、适用范围给对照；产出两张表——速率系数表给研究、约束变化表给风控。方法协议见<a href="/quant/obd-eventstudy-micro">事件研究的微观版本</a>。错法：只用生效日做窗口，漏掉过渡期行为。</p>',20)),(A(),t(i,null,{default:B(()=>[l(n,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIVE%5B%22%E4%BA%94%E5%85%83%E7%BB%84%EF%BC%9A%E6%97%B6%E7%82%B9%20%E8%BD%BD%E8%8D%B7%20%E9%A2%84%E6%9C%9F%20%E7%AA%97%E5%8F%A3%20%E6%B5%81%E9%87%8F%22%5D%20--%3E%20FAM%5B%22%E4%BA%8B%E4%BB%B6%E8%B0%B1%E7%B3%BB%EF%BC%9A%E8%B4%A2%E6%8A%A5%20%E8%B0%83%E6%95%B4%20%E5%88%B0%E6%9C%9F%20%E5%AE%8F%E8%A7%82%20%E5%88%B6%E5%BA%A6%22%5D%0A%20%20FAM%20--%3E%20SIG%5B%22%E4%BF%A1%E5%8F%B7%E4%B8%8E%E6%8C%81%E4%BB%93%EF%BC%9A%E6%BC%82%E7%A7%BB%20%E4%B8%BB%E7%AA%97%E5%89%AF%E7%AA%97%20%E6%BA%A2%E4%BB%B7%E8%B4%A6%22%5D%0A%20%20FAM%20--%3E%20MICRO%5B%22%E5%BE%AE%E8%A7%82%E6%B5%8B%E9%87%8F%EF%BC%9A%E9%80%9F%E7%8E%87%E8%A1%A8%E4%B8%8E%E8%A1%A5%E5%81%BF%E7%BB%93%E6%9E%84%22%5D%0A%20%20FAM%20--%3E%20RISK%5B%22%E9%A3%8E%E6%8E%A7%EF%BC%9ABernoulli%20%E4%BA%8B%E4%BB%B6%E6%97%A5%E7%9B%B8%E5%85%B3%20%E6%8B%A5%E6%8C%A4%22%5D%0A%20%20SIG%20--%3E%20CASE%5B%22%E6%A1%88%E4%BE%8B%E5%BA%93%EF%BC%9A%E9%94%99%E6%B3%95%E4%B8%8E%E6%8D%A2%E6%8C%A1%E7%82%B9%22%5D%0A%20%20MICRO%20--%3E%20CASE%0A%20%20RISK%20--%3E%20CASE%0A%20%20CASE%20--%3E%20MAP%5B%22%E8%AF%BE%E7%A8%8B%E5%9C%B0%E5%9B%BE%EF%BC%9A%E8%B0%B1%E7%B3%BB%E5%9D%90%E6%A0%87%E4%B8%8A%E7%9A%84%E4%BA%8B%E4%BB%B6%E7%AD%96%E7%95%A5%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("课程的主线机制可以压成三句。第一句："),e("strong",null,"事件化把「日程」变成研究对象"),E("——日历公开是双刃，它让 alpha 可研究（五元组），也让它可复制（拥挤）；溢价随资本周期起伏，这是事件策略的宏观宿命。第二句："),e("strong",null,"谱系坐标决定方法的迁移边界"),E("——载荷可预测的事件走流量与执行的账，载荷不可预测的事件走预期差与统计的账；跨格搬运窗口与对照设计，是这一族策略最常见的研究错误。第三句："),e("strong",null,"微观测量是策略参数的来源"),E("——价格发现速度、流动性补偿结构、对冲流符号，从速率表读执行与风控参数，不从收益平均值里猜。三句合起来：事件策略的工程化不是找一个效应，而是把五元组、谱系坐标、速率表与三层风控装进同一张事件表，让每一次事件从登记到退出走同一条管线。")],-1)),(A(),t(i,null,{default:B(()=>[l(n,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22%E4%B8%80%E4%B8%AA%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20Q%7B%22%E8%BD%BD%E8%8D%B7%E5%8F%AF%E9%A2%84%E6%B5%8B%E5%90%97%3F%22%7D%0A%20%20Q%20--%20%22%E5%8F%AF%E9%A2%84%E6%B5%8B%3A%20%E8%A7%84%E5%88%99%E6%88%96%E5%85%AC%E5%BC%80%E6%8C%81%E4%BB%93%22%20--%3E%20FLOW%5B%22%E8%B5%B0%E6%B5%81%E9%87%8F%E8%B4%A6%3A%20%E6%8E%A8%E7%AE%97%20%CE%94w%20%E4%B8%8E%E5%AF%B9%E5%86%B2%E6%B5%81%22%5D%0A%20%20FLOW%20--%3E%20EXEC%5B%22%E6%96%B9%E6%B3%95%E9%87%8D%E5%BF%83%3A%20%E6%89%A7%E8%A1%8C%E4%B8%8E%E7%AB%9E%E4%BB%B7%22%5D%0A%20%20Q%20--%20%22%E4%B8%8D%E5%8F%AF%E9%A2%84%E6%B5%8B%3A%20%E5%A4%A7%E5%B0%8F%E6%9C%AA%E7%9F%A5%22%20--%3E%20SURP%5B%22%E8%B5%B0%E9%A2%84%E6%9C%9F%E5%B7%AE%E8%B4%A6%3A%20SUE%20%E4%B8%8E%E6%A0%87%E5%87%86%E5%8C%96%E6%84%8F%E5%A4%96%22%5D%0A%20%20SURP%20--%3E%20STAT%5B%22%E6%96%B9%E6%B3%95%E9%87%8D%E5%BF%83%3A%20%E7%AA%97%E5%8F%A3%E4%B8%8E%E7%BB%9F%E8%AE%A1%E5%8A%9F%E6%95%88%22%5D%0A%20%20EXEC%20--%3E%20SAME%5B%22%E5%90%8C%E4%B8%80%E5%BC%A0%E4%BA%8B%E4%BB%B6%E8%A1%A8%3A%20%E7%99%BB%E8%AE%B0%E5%88%B0%E9%80%80%E5%87%BA%E4%B8%80%E6%9D%A1%E7%AE%A1%E7%BA%BF%22%5D%0A%20%20STAT%20--%3E%20SAME%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">常见误区：把某一格的窗口与对照设计直接搬到另一格。例如用财报的「公告后 60 日漂移窗」去研究指数调整的生效日，生搬过去会把可推算的执行流误读成漂移，估出根本不存在的持续效应。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束之后明确不覆盖的部分：纯公告文本的信息提取（语言层见<a href="/quant/earnings-call-tone">电话会语气</a>与文本因子一课的展开）、波动率产品的对冲细节、以及各市场制度参数的逐项对照；事件策略的执行层（参与率、母单调度）属于执行课程的账。合规边界全课程一致：事件库只装公开时点与公开信息，预告、传闻与内幕不进表——这条线在本课程的每一课都是同一条。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五个案例走完谱系坐标：载荷可预测性从规则流量、公开持仓到完全未知，方法随之换挡。</li><li>五元组是贯穿工具；错法集中在时点错配、窗口混账与跨格搬运协议。</li><li>三句主线：日程是研究对象、谱系坐标定方法边界、微观速率表是参数来源。</li><li>风控三层配三类限额：左尾情景、事件日暴露集中度、拥挤三只表。</li><li>本课程到此收束：从财报事件化到拥挤风控，事件表是全部结论的落点。</li><li>出处：Bernard and Thomas, <em>JAR</em>, 1989/1990；Chen, Noronha and Singal, <em>JF</em>, 2004；Ni, Pearson, Poteshman and Whitefoot, <em>JFE</em>, 2005；Fleming and Remolona, <em>JF</em>, 1999；MacKinlay, <em>JEL</em>, 1997；其余口径见各课。</li></ul>',5))])}const q=o(h,[["render",p]]);export{f as __pageData,q as default};
